	@Test
	void aPipelineQuotePricesOnlyTheWorkerGroupItsAdmissionCanUse() throws Exception {
		Map<String, String> previous = new LinkedHashMap<>();
		set(previous, "rdf4j.lmdb.parallel.enabled", "true");
		set(previous, "rdf4j.lmdb.parallel.threads", "8");
		set(previous, "rdf4j.lmdb.parallel.maxTasks", "8");
		set(previous, "rdf4j.lmdb.parallel.minWorkEstimate", "0");
		set(previous, "rdf4j.lmdb.parallel.rangePartition.enabled", "false");
		try {
			StatsSource source = new StatsSource(1_000_000L).predicate(1L, 3D, 30_000L)
					.predicate(2L, 3D, 30_000L);
			RowState row = row(source);
			MultiJoinPlan join = new MultiJoinPlan(
					new PatternPlan[] { edge(0, 1L, 1, 90_000D), edge(0, 2L, 2, 90_000D) },
					new MaskedFilter[0]);
			NativeRowsStep step = new NativeRowsStep(source, join, row.layout, new int[] { 0, 1, 2 },
					new String[] { "s", "a", "b" }, false, new int[0], new boolean[0], 0L, -1L, false,
					null, null, null, Set.of(), null, null);
			// Only reserve task capacity. No executor, source, worker, or cursor is opened by this test.
			try (LmdbNativeParallelPipelines.TaskReservation otherQuery = LmdbNativeParallelPipelines
					.tryReserveTasks(false, 6)) {
				assertThat(otherQuery).isNotNull();
				assertThat(otherQuery.grantedWorkers()).isEqualTo(6);
				try (LmdbNativeParallelPipelines.TaskReservation available = LmdbNativeParallelPipelines
						.quoteTasks(true, 8)) {
					assertThat(available).isNotNull();
					assertThat(available.grantedWorkers()).isEqualTo(2);
					try (LmdbNativeStrategyProposal<RowCursor> proposal = LmdbNativeParallelPipelines.propose(step,
							row)) {
						assertThat(proposal).isNotNull();
						LmdbNativeCostQuote quote = LmdbNativeOfferBridge.quote(proposal);
						assertThat(quote.startup().expected(Feature.WORKER_START))
								.as("the planned pipeline has two workers, not the configured maximum of eight")
								.isEqualTo(available.grantedWorkers());
					}
				}
			} finally {
				row.memoryScope.close();
			}
		} finally {
			previous.forEach((key, value) -> {
				if (value == null) {
					System.clearProperty(key);
				} else {
					System.setProperty(key, value);
				}
			});
		}
	}

	private static void set(Map<String, String> previous, String key, String value) {
		previous.put(key, System.getProperty(key));
		System.setProperty(key, value);
	}
